'use strict';

var jrpc = require('../jrpc.js');
var compatibilityUtils = require('./compatibility-utils.js');
var jrpcEngineV2 = require('./jrpcEngineV2.js');

/**
 * The asLegacyMiddleware implementation.
 *
 * @param engineOrMiddleware - A V2 engine or V2 middleware.
 * @param rest - Any additional V2 middleware when the first argument is a middleware.
 * @returns The legacy middleware.
 */
function asLegacyMiddleware(engineOrMiddleware, ...rest) {
  const v2Middleware = typeof engineOrMiddleware === "function" ? jrpcEngineV2.JRPCEngineV2.create({
    middleware: [engineOrMiddleware, ...rest]
  }).asMiddleware() : engineOrMiddleware.asMiddleware();
  return jrpc.createAsyncMiddleware(async (req, res, next) => {
    const request = compatibilityUtils.fromLegacyRequest(req);
    const context = compatibilityUtils.makeContext(req);
    let modifiedRequest;
    const result = await v2Middleware({
      request,
      context,
      next: finalRequest => {
        modifiedRequest = finalRequest;
        return Promise.resolve(undefined);
      }
    });
    if (modifiedRequest !== undefined && modifiedRequest !== request) {
      Object.assign(req, compatibilityUtils.deepClone(modifiedRequest));
    }
    compatibilityUtils.propagateToRequest(req, context);
    if (result !== undefined) {
      // Unclear why the `as unknown` is needed here, but the cast is safe.
      res.result = compatibilityUtils.deepClone(result);
      return undefined;
    }
    return next();
  });
}

exports.asLegacyMiddleware = asLegacyMiddleware;
